819	    std::string WebSocketTransport::getMergedChunks() const
820	    {
821	        size_t length = 0;
822	        for (auto&& chunk : _chunks)
823	        {
824	            length += chunk.size();
825	        }
826	
827	        std::string msg;
828	        msg.reserve(length);
829	
830	        for (auto&& chunk : _chunks)
831	        {
832	            msg += chunk;
833	        }
834	
835	        return msg;
836	    }
