15	using namespace ix;
16	
17	namespace
18	{
19	    class WebSocketClient
20	    {
21	    public:
22	        WebSocketClient(int port);
23	
24	        void subscribe(const std::string& channel);
25	        void start();
26	        void stop();
27	        void stop(uint16_t code, const std::string& reason);
28	        bool isReady() const;
29	
30	        uint16_t getCloseCode();
31	        const std::string& getCloseReason();
32	        bool getCloseRemote();
33	
34	        bool hasConnectionError() const;
35	
36	    private:
37	        ix::WebSocket _webSocket;
38	        int _port;
39	
40	        mutable std::mutex _mutexCloseData;
41	        uint16_t _closeCode;
42	        std::string _closeReason;
43	        bool _closeRemote;
44	        std::atomic<bool> _connectionError;
45	    };
46	
47	    WebSocketClient::WebSocketClient(int port)
48	        : _port(port)
49	        , _closeCode(0)
50	        , _closeReason(std::string(""))
51	        , _closeRemote(false)
52	        , _connectionError(false)
53	    {
54	        ;
55	    }
56	
57	    bool WebSocketClient::hasConnectionError() const
58	    {
59	        return _connectionError;
60	    }
61	
62	    bool WebSocketClient::isReady() const
63	    {
64	        return _webSocket.getReadyState() == ix::ReadyState::Open;
65	    }
66	
67	    uint16_t WebSocketClient::getCloseCode()
68	    {
69	        std::lock_guard<std::mutex> lck(_mutexCloseData);
70	
71	        return _closeCode;
72	    }
73	
74	    const std::string& WebSocketClient::getCloseReason()
75	    {
76	        std::lock_guard<std::mutex> lck(_mutexCloseData);
77	
78	        return _closeReason;
79	    }
80	
81	    bool WebSocketClient::getCloseRemote()
82	    {
83	        std::lock_guard<std::mutex> lck(_mutexCloseData);
84	
85	        return _closeRemote;
86	    }
87	
88	    void WebSocketClient::stop()
89	    {
90	        _webSocket.stop();
91	    }
92	
93	    void WebSocketClient::stop(uint16_t code, const std::string& reason)
94	    {
95	        _webSocket.stop(code, reason);
96	    }
97	
98	    void WebSocketClient::start()
99	    {
100	        std::string url;
101	        {
102	            std::stringstream ss;
103	            ss << "ws://localhost:" << _port << "/";
104	
105	            url = ss.str();
106	        }
107	
108	        _webSocket.setUrl(url);
109	        _webSocket.disableAutomaticReconnection();
110	
111	        std::stringstream ss;
112	        log(std::string("Connecting to url: ") + url);
113	
114	        _webSocket.setOnMessageCallback([this](const ix::WebSocketMessagePtr& msg) {
115	            std::stringstream ss;
116	            if (msg->type == ix::WebSocketMessageType::Open)
117	            {
118	                log("client connected");
119	            }
120	            else if (msg->type == ix::WebSocketMessageType::Close)
121	            {
122	                std::stringstream ss;
123	                ss << "client disconnected(" << msg->closeInfo.code << "," << msg->closeInfo.reason
124	                   << ")";
125	                log(ss.str());
126	
127	                std::lock_guard<std::mutex> lck(_mutexCloseData);
128	
129	                _closeCode = msg->closeInfo.code;
130	                _closeReason = std::string(msg->closeInfo.reason);
131	                _closeRemote = msg->closeInfo.remote;
132	            }
133	            else if (msg->type == ix::WebSocketMessageType::Error)
