#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <zlib.h>

static int try_inflate(const char* label, const unsigned char* in, size_t n) {
    z_stream s; memset(&s, 0, sizeof(s));
    int r = inflateInit2(&s, -15);
    if (r != Z_OK) { printf("%s: init failed %d\n", label, r); return r; }

    unsigned char* fixed = malloc(n + 4);
    memcpy(fixed, in, n);
    fixed[n]=0; fixed[n+1]=0; fixed[n+2]=0xff; fixed[n+3]=0xff;

    s.avail_in = (uInt)(n+4);
    s.next_in = fixed;

    unsigned char outbuf[100];
    int produced = 0; int lastret = 0; int iters = 0;
    do {
        s.avail_out = sizeof(outbuf);
        s.next_out = outbuf;
        lastret = inflate(&s, Z_SYNC_FLUSH);
        produced += (int)(sizeof(outbuf) - s.avail_out);
        if (++iters > 100) break;
    } while (s.avail_out == 0 && lastret != Z_DATA_ERROR && lastret != Z_STREAM_END);

    printf("%s: lastret=%d (%s) produced=%d msg=%s\n", label, lastret,
        lastret==Z_OK?"Z_OK":lastret==Z_DATA_ERROR?"Z_DATA_ERROR":
        lastret==Z_STREAM_END?"Z_STREAM_END":lastret==Z_BUF_ERROR?"Z_BUF_ERROR":
        lastret==Z_NEED_DICT?"Z_NEED_DICT":"other",
        produced, s.msg ? s.msg : "(null)");
    inflateEnd(&s);
    free(fixed);
    return lastret;
}

int main(void) {
    unsigned char b1[] = {0x07};
    try_inflate("0x07", b1, 1);

    /* build a valid fixed-huffman stream for "hello" via deflate raw */
    z_stream c; memset(&c,0,sizeof(c));
    deflateInit2(&c, Z_DEFAULT_COMPRESSION, Z_DEFLATED, -15, 4, Z_DEFAULT_STRATEGY);
    const char* text = "Aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
                       "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
    unsigned char comp[200];
    c.avail_in = (uInt)strlen(text);
    c.next_in = (unsigned char*)text;
    c.avail_out = sizeof(comp);
    c.next_out = comp;
    deflate(&c, Z_SYNC_FLUSH);
    size_t cn = sizeof(comp) - c.avail_out;
    /* strip trailing 00 00 ff ff */
    if (cn >= 4) cn -= 4;
    deflateEnd(&c);
    printf("valid compressed prefix len=%zu\n", cn);

    /* valid prefix + garbage byte 0x07 */
    unsigned char* mix = malloc(cn + 1);
    memcpy(mix, comp, cn); mix[cn] = 0x07;
    try_inflate("valid+0x07", mix, cn+1);

    /* valid alone */
    try_inflate("valid", comp, cn);
    free(mix);
    return 0;
}
