2	 *  IXWebSocketPerMessageDeflateOptions.cpp
3	 *  Author: Benjamin Sergeant
4	 *  Copyright (c) 2018 Machine Zone, Inc. All rights reserved.
5	 */
6	
7	#include "IXWebSocketPerMessageDeflateOptions.h"
8	
9	#include <algorithm>
10	#include <cctype>
11	#include <sstream>
12	
13	namespace ix
14	{
15	    /// Default values as defined in the RFC
16	    const uint8_t WebSocketPerMessageDeflateOptions::kDefaultServerMaxWindowBits = 15;
17	    const uint8_t WebSocketPerMessageDeflateOptions::kDefaultClientMaxWindowBits = 15;
18	#ifdef IXWEBSOCKET_USE_ZLIB
19	    static const uint8_t minServerMaxWindowBits = 8;
20	    static const uint8_t maxServerMaxWindowBits = 15;
21	    static const uint8_t minClientMaxWindowBits = 8;
22	    static const uint8_t maxClientMaxWindowBits = 15;
23	#endif
24	
25	    WebSocketPerMessageDeflateOptions::WebSocketPerMessageDeflateOptions(
26	        bool enabled,
27	        bool clientNoContextTakeover,
28	        bool serverNoContextTakeover,
29	        uint8_t clientMaxWindowBits,
30	        uint8_t serverMaxWindowBits,
31	        bool sendClientServerMaxWindowBits)
32	    {
33	        _enabled = enabled;
34	        _clientNoContextTakeover = clientNoContextTakeover;
35	        _serverNoContextTakeover = serverNoContextTakeover;
36	        _clientMaxWindowBits = clientMaxWindowBits;
37	        _serverMaxWindowBits = serverMaxWindowBits;
38	        _sendClientServerMaxWindowBits = sendClientServerMaxWindowBits;
39	
40	        sanitizeClientMaxWindowBits();
41	    }
42	
43	    //
44	    // Four extension parameters are defined for "permessage-deflate" to
45	    // help endpoints manage per-connection resource usage.
46	    //
47	    // - "server_no_context_takeover"
48	    // - "client_no_context_takeover"
49	    // - "server_max_window_bits"
50	    // - "client_max_window_bits"
51	    //
52	    // Server response could look like that:
53	    //
54	    // Sec-WebSocket-Extensions: permessage-deflate; client_no_context_takeover;
55	    // server_no_context_takeover
56	    //
57	    WebSocketPerMessageDeflateOptions::WebSocketPerMessageDeflateOptions(std::string extension)
58	    {
59	        extension = removeSpaces(extension);
60	
61	        _enabled = false;
62	        _clientNoContextTakeover = false;
63	        _serverNoContextTakeover = false;
64	        _sendClientServerMaxWindowBits = true;
65	        _clientMaxWindowBits = kDefaultClientMaxWindowBits;
66	        _serverMaxWindowBits = kDefaultServerMaxWindowBits;
67	
68	#ifdef IXWEBSOCKET_USE_ZLIB
69	        // Split by ;
70	        std::string token;
71	        std::stringstream tokenStream(extension);
72	
73	        while (std::getline(tokenStream, token, ';'))
74	        {
75	            if (token == "permessage-deflate")
76	            {
77	                _enabled = true;
78	            }
79	
80	            if (token == "server_no_context_takeover")
81	            {
82	                _serverNoContextTakeover = true;
83	            }
84	
85	            if (token == "client_no_context_takeover")
86	            {
87	                _clientNoContextTakeover = true;
88	            }
89	
90	            if (startsWith(token, "server_max_window_bits="))
91	            {
92	                uint8_t x = strtol(token.substr(token.find_last_of("=") + 1).c_str(), nullptr, 10);
93	
94	                // Sanitize values to be in the proper range [8, 15] in
95	                // case a server would give us bogus values
96	                _serverMaxWindowBits =
97	                    std::min(maxServerMaxWindowBits, std::max(x, minServerMaxWindowBits));
98	            }
99	
100	            if (startsWith(token, "client_max_window_bits="))
101	            {
102	                uint8_t x = strtol(token.substr(token.find_last_of("=") + 1).c_str(), nullptr, 10);
103	
104	                // Sanitize values to be in the proper range [8, 15] in
105	                // case a server would give us bogus values
106	                _clientMaxWindowBits =
107	                    std::min(maxClientMaxWindowBits, std::max(x, minClientMaxWindowBits));
108	
109	                sanitizeClientMaxWindowBits();
110	            }
111	        }
112	#endif
113	    }
114	
115	    void WebSocketPerMessageDeflateOptions::sanitizeClientMaxWindowBits()
116	    {
117	        // zlib/deflate has a bug with windowsbits == 8, so we silently upgrade it to 9
118	        // See https://bugs.chromium.org/p/chromium/issues/detail?id=691074
119	        if (_clientMaxWindowBits == 8)
120	        {
121	            _clientMaxWindowBits = 9;
122	        }
123	    }
124	
125	    std::string WebSocketPerMessageDeflateOptions::generateHeader()
126	    {
127	#ifdef IXWEBSOCKET_USE_ZLIB
128	        std::stringstream ss;
129	        ss << "Sec-WebSocket-Extensions: permessage-deflate";
130	
131	        if (_clientNoContextTakeover) ss << "; client_no_context_takeover";
132	        if (_serverNoContextTakeover) ss << "; server_no_context_takeover";
133	
134	        if (_sendClientServerMaxWindowBits)
135	        {
136	            ss << "; server_max_window_bits=" << static_cast<int>(_serverMaxWindowBits);
137	            ss << "; client_max_window_bits=" << static_cast<int>(_clientMaxWindowBits);
138	        }
139	
140	        ss << "\r\n";
141	
142	        return ss.str();
143	#else
144	        return std::string();
145	#endif
146	    }
147	
148	    bool WebSocketPerMessageDeflateOptions::enabled() const
149	    {
150	#ifdef IXWEBSOCKET_USE_ZLIB
151	        return _enabled;
152	#else
153	        return false;
154	#endif
155	    }
156	
157	    bool WebSocketPerMessageDeflateOptions::getClientNoContextTakeover() const
158	    {
159	        return _clientNoContextTakeover;
160	    }
161	
162	    bool WebSocketPerMessageDeflateOptions::getServerNoContextTakeover() const
163	    {
164	        return _serverNoContextTakeover;
165	    }
166	
167	    uint8_t WebSocketPerMessageDeflateOptions::getClientMaxWindowBits() const
168	    {
169	        return _clientMaxWindowBits;
170	    }
171	
172	    uint8_t WebSocketPerMessageDeflateOptions::getServerMaxWindowBits() const
173	    {
174	        return _serverMaxWindowBits;
175	    }
176	
177	    bool WebSocketPerMessageDeflateOptions::getSendClientServerMaxWindowBits() const
178	    {
179	        return _sendClientServerMaxWindowBits;
180	    }
181	
182	    bool WebSocketPerMessageDeflateOptions::startsWith(const std::string& str,
183	                                                       const std::string& start)
184	    {
185	        return str.compare(0, start.length(), start) == 0;
186	    }
187	
188	    std::string WebSocketPerMessageDeflateOptions::removeSpaces(const std::string& str)
189	    {
