/*
 * IXWebSocketDecompressionFailureTest.cpp
 *
 * Verifies that a message whose compressed payload is rejected by zlib fails
 * the whole message and tears down the connection, on both client and server
 * sides, for both text and binary messages.
 */

#include "IXTest.h"
#include "catch_amalgamated.hpp"
#include <atomic>
#include <chrono>
#include <cstring>
#include <ixwebsocket/IXGetFreePort.h>
#include <ixwebsocket/IXWebSocket.h>
#include <ixwebsocket/IXWebSocketCloseConstants.h>
#include <ixwebsocket/IXWebSocketHandshakeKeyGen.h>
#include <ixwebsocket/IXWebSocketPerMessageDeflateCodec.h>
#include <ixwebsocket/IXWebSocketServer.h>
#include <list>
#include <mutex>
#include <netinet/in.h>
#include <netinet/tcp.h>
#include <string>
#include <sys/socket.h>
#include <thread>
#include <unistd.h>
#include <vector>
#include <zlib.h>

using namespace ix;

namespace
{
    //
    // A minimal raw WebSocket peer speaking permessage-deflate over TCP.
    //
    class RawPeer
    {
    public:
        ~RawPeer()
        {
            reset();
        }

        // Listen so a websocket *client* can connect to this peer (peer acts as
        // a permessage-deflate server).
        bool listen()
        {
            _listenFd = ::socket(AF_INET, SOCK_STREAM, 0);
            REQUIRE(_listenFd >= 0);
            int yes = 1;
            setsockopt(_listenFd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(yes));

            sockaddr_in addr {};
            addr.sin_family = AF_INET;
            addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
            addr.sin_port = 0;
            REQUIRE(bind(_listenFd, (sockaddr*) &addr, sizeof(addr)) == 0);
            REQUIRE(::listen(_listenFd, 1) == 0);

            socklen_t len = sizeof(addr);
            REQUIRE(getsockname(_listenFd, (sockaddr*) &addr, &len) == 0);
            _port = ntohs(addr.sin_port);
            return true;
        }

        int port() const
        {
            return _port;
        }

        // Block until one client has connected and finish the handshake (the
        // raw peer is the WebSocket server side of this exchange).
        bool acceptWithDeflate(const std::string& responseExtensions)
        {
            _fd = ::accept(_listenFd, nullptr, nullptr);
            REQUIRE(_fd >= 0);
            int yes = 1;
            setsockopt(_fd, IPPROTO_TCP, TCP_NODELAY, &yes, sizeof(yes));

            // Read the HTTP upgrade request
            std::string request;
            char buf[1024];
            while (request.find("\r\n\r\n") == std::string::npos)
            {
                ssize_t n = ::recv(_fd, buf, sizeof(buf), 0);
                REQUIRE(n > 0);
                request.append(buf, (size_t) n);
            }

            // Extract Sec-WebSocket-Key
            std::string key;
            const std::string keyHeader = "Sec-WebSocket-Key:";
            auto pos = request.find(keyHeader);
            REQUIRE(pos != std::string::npos);
            pos += keyHeader.size();
            while (pos < request.size() && (request[pos] == ' ' || request[pos] == '\t')) ++pos;
            auto end = request.find("\r\n", pos);
            key = request.substr(pos, end - pos);

            char accept[29] = {};
            WebSocketHandshakeKeyGen::generate(key, accept);

            std::string response = "HTTP/1.1 101 Switching Protocols\r\n"
                                   "Upgrade: websocket\r\n"
                                   "Connection: Upgrade\r\n"
                                   "Sec-WebSocket-Accept: " +
                                   std::string(accept) + "\r\n";
            if (!responseExtensions.empty())
            {
                response += "Sec-WebSocket-Extensions: " + responseExtensions + "\r\n";
            }
            response += "\r\n";

            REQUIRE(sendAll(response));
            return true;
        }

        // Connect this peer to a websocket *server* and perform the client
        // handshake requesting permessage-deflate.
        bool connect(int port)
        {
            _fd = ::socket(AF_INET, SOCK_STREAM, 0);
            REQUIRE(_fd >= 0);
            int yes = 1;
            setsockopt(_fd, IPPROTO_TCP, TCP_NODELAY, &yes, sizeof(yes));

            sockaddr_in addr {};
            addr.sin_family = AF_INET;
            addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
            addr.sin_port = htons((uint16_t) port);
            REQUIRE(::connect(_fd, (sockaddr*) &addr, sizeof(addr)) == 0);

            std::string request =
                "GET / HTTP/1.1\r\n"
                "Host: localhost\r\n"
                "Upgrade: websocket\r\n"
                "Connection: Upgrade\r\n"
                "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n"
                "Sec-WebSocket-Version: 13\r\n"
                "Sec-WebSocket-Extensions: permessage-deflate\r\n"
                "\r\n";
            REQUIRE(sendAll(request));

            std::string response;
            char buf[1024];
            while (response.find("\r\n\r\n") == std::string::npos)
            {
                ssize_t n = ::recv(_fd, buf, sizeof(buf), 0);
                REQUIRE(n > 0);
                response.append(buf, (size_t) n);
            }
            REQUIRE(response.find("101") != std::string::npos);
            REQUIRE(response.find("permessage-deflate") != std::string::npos);
            return true;
        }

        // Build a websocket frame.
        static std::string frame(int opcode,
                                 bool fin,
                                 bool rsv1,
                                 const std::string& payload,
                                 bool mask)
        {
            std::string out;
            uint8_t b0 = (uint8_t) opcode;
            if (fin) b0 |= 0x80;
            if (rsv1) b0 |= 0x40;
            out.push_back((char) b0);

            uint8_t maskBit = mask ? 0x80 : 0;
            uint64_t n = payload.size();
            if (n < 126)
            {
                out.push_back((char) (maskBit | (uint8_t) n));
            }
            else if (n <= 0xffff)
            {
                out.push_back((char) (maskBit | 126));
                out.push_back((char) ((n >> 8) & 0xff));
                out.push_back((char) (n & 0xff));
            }
            else
            {
                out.push_back((char) (maskBit | 127));
                for (int i = 7; i >= 0; --i)
                {
                    out.push_back((char) ((n >> (8 * i)) & 0xff));
                }
            }

            uint8_t key[4] = {0x12, 0x34, 0x56, 0x78};
            if (mask)
            {
                for (int i = 0; i < 4; ++i) out.push_back((char) key[i]);
            }

            for (uint64_t i = 0; i < n; ++i)
            {
                char c = payload[i];
                if (mask) c ^= (char) key[i & 3];
                out.push_back(c);
            }
            return out;
        }

        bool sendAll(const std::string& data)
        {
            size_t sent = 0;
            while (sent < data.size())
            {
                ssize_t n = ::send(_fd, data.data() + sent, data.size() - sent, 0);
                if (n <= 0) return false;
                sent += (size_t) n;
            }
            return true;
        }

        void sendFrame(int opcode,
                       bool fin,
                       bool rsv1,
                       const std::string& payload,
                       bool mask)
        {
            REQUIRE(sendAll(frame(opcode, fin, rsv1, payload, mask)));
        }

        // Send the given bytes one at a time, to exercise header/payload
        // reads that arrive in several socket reads.
        void sendByteByByte(const std::string& data)
        {
            for (char c : data)
            {
                REQUIRE(sendAll(std::string(1, c)));
                ix::msleep(1);
            }
        }

        struct ParsedFrame
        {
            bool fin;
            bool rsv1;
            int opcode;
            std::string payload;
        };

        // Read one frame (blocking). Returns false on clean/error close.
        bool recvFrame(ParsedFrame& frame)
        {
            uint8_t h[2];
            if (!recvExact(h, 2)) return false;
            frame.fin = (h[0] & 0x80) != 0;
            frame.rsv1 = (h[0] & 0x40) != 0;
            frame.opcode = h[0] & 0x0f;
            bool masked = (h[1] & 0x80) != 0;
            uint64_t n = h[1] & 0x7f;
            std::string ext;
            if (n == 126)
            {
                uint8_t e[2];
                if (!recvExact(e, 2)) return false;
                n = ((uint64_t) e[0] << 8) | e[1];
            }
            else if (n == 127)
            {
                uint8_t e[8];
                if (!recvExact(e, 8)) return false;
                n = 0;
                for (int i = 0; i < 8; ++i) n = (n << 8) | e[i];
            }
            uint8_t key[4] = {};
            if (masked)
            {
                if (!recvExact(key, 4)) return false;
            }
            frame.payload.resize((size_t) n);
            if (n > 0 && !recvExact((uint8_t*) &frame.payload[0], (size_t) n)) return false;
            if (masked)
            {
                for (uint64_t i = 0; i < n; ++i) frame.payload[i] ^= (char) key[i & 3];
            }
            return true;
        }

        void closePeer()
        {
            if (_fd >= 0)
            {
                ::close(_fd);
                _fd = -1;
            }
        }

        void reset()
        {
            closePeer();
            if (_listenFd >= 0)
            {
                ::close(_listenFd);
                _listenFd = -1;
            }
        }

        // Send back a CLOSE frame echoing code and reason (server->client
        // frames are unmasked in this helper).
        void sendCloseEcho(uint16_t code, const std::string& reason, bool mask)
        {
            std::string payload;
            payload.push_back((char) ((code >> 8) & 0xff));
            payload.push_back((char) (code & 0xff));
            payload += reason;
            sendFrame(8, true, false, payload, mask);
        }

    private:
        bool recvExact(uint8_t* dst, size_t n)
        {
            size_t got = 0;
            while (got < n)
            {
                ssize_t r = ::recv(_fd, dst + got, n - got, 0);
                if (r <= 0) return false;
                got += (size_t) r;
            }
            return true;
        }

        int _listenFd = -1;
        int _fd = -1;
        int _port = 0;
    };

    //
    // Raw DEFLATE compression (raw deflate, sync flush, trailing
    // 00 00 ff ff stripped), matching what permessage-deflate puts on the wire.
    //
    std::string rawCompress(const std::string& in)
    {
        z_stream stream;
        memset(&stream, 0, sizeof(stream));
        REQUIRE(deflateInit2(&stream,
                            Z_DEFAULT_COMPRESSION,
                            Z_DEFLATED,
                            -15,
                            4,
                            Z_DEFAULT_STRATEGY) == Z_OK);

        std::vector<uint8_t> out(in.size() + 64);
        stream.avail_in = (uInt) in.size();
        stream.next_in = (const_cast<uint8_t*>((const uint8_t*) in.data()));
        stream.avail_out = (uInt) out.size();
        stream.next_out = out.data();
        REQUIRE(deflate(&stream, Z_SYNC_FLUSH) == Z_OK);
        size_t n = out.size() - stream.avail_out;
        deflateEnd(&stream);

        // strip the trailing 00 00 ff ff empty block marker
        REQUIRE(n >= 4);
        n -= 4;
        return std::string((char*) out.data(), n);
    }

    struct Event
    {
        WebSocketMessageType type;
        std::string str;
        size_t wireSize = 0;
        bool binary = false;
        bool decompressionError = false;
        std::string reason;
        uint16_t closeCode = 0;
        std::string closeReason;
        bool closeRemote = false;
    };

    struct EventLog
    {
        std::mutex mutex;
        std::list<Event> events;
        std::atomic<bool> sendInErrorCallbackFailed {false};
        std::atomic<bool> ready {false};
        WebSocket* ws = nullptr;

        void push(const WebSocketMessagePtr& msg)
        {
            Event e;
            e.type = msg->type;
            e.str = msg->str;
            e.wireSize = msg->wireSize;
            e.binary = msg->binary;
            e.decompressionError = msg->errorInfo.decompressionError;
            e.reason = msg->errorInfo.reason;
            e.closeCode = msg->closeInfo.code;
            e.closeReason = msg->closeInfo.reason;
            e.closeRemote = msg->closeInfo.remote;

            if (msg->type == WebSocketMessageType::Error &&
                msg->errorInfo.decompressionError && ws)
            {
                // Sending from within the error callback must fail: the
                // connection must already be closing.
                auto info = ws->send("should-fail", false);
                sendInErrorCallbackFailed = !info.success;
            }

            std::lock_guard<std::mutex> lock(mutex);
            events.push_back(e);
            if (msg->type == WebSocketMessageType::Open) ready = true;
        }

        std::vector<Event> snapshot()
        {
            std::lock_guard<std::mutex> lock(mutex);
            return std::vector<Event>(events.begin(), events.end());
        }

        bool waitUntilClosed(int timeoutMs = 5000)
        {
            auto deadline = std::chrono::steady_clock::now() +
                            std::chrono::milliseconds(timeoutMs);
            while (std::chrono::steady_clock::now() < deadline)
            {
                {
                    std::lock_guard<std::mutex> lock(mutex);
                    for (auto& e : events)
                    {
                        if (e.type == WebSocketMessageType::Close) return true;
                    }
                }
                ix::msleep(10);
            }
            return false;
        }

        bool waitForOpen(int timeoutMs = 5000)
        {
            auto deadline = std::chrono::steady_clock::now() +
                            std::chrono::milliseconds(timeoutMs);
            while (std::chrono::steady_clock::now() < deadline)
            {
                if (ready) return true;
                ix::msleep(10);
            }
            return false;
        }
    };

    // Count events of a given type.
    size_t countEvents(const std::vector<Event>& events, WebSocketMessageType type)
    {
        size_t n = 0;
        for (auto& e : events)
            if (e.type == type) ++n;
        return n;
    }

    const Event* findEvent(const std::vector<Event>& events, WebSocketMessageType type)
    {
        for (auto& e : events)
            if (e.type == type) return &e;
        return nullptr;
    }

    // ---- client side: raw server feeds bad compressed frames to a client ----
    void runClientCase(bool binary,
                       bool echoClose,
                       const std::string& badPayload,
                       size_t expectedWireSize,
                       const std::function<void(RawPeer&)>& injectAfterError,
                       const std::function<void(RawPeer&, bool)>& sendBad)
    {
        RawPeer peer;
        REQUIRE(peer.listen());

        WebSocket ws;
        EventLog log;
        log.ws = &ws;
        ws.setUrl("ws://localhost:" + std::to_string(peer.port()) + "/");
        ws.disableAutomaticReconnection();
        ws.enablePerMessageDeflate();
        ws.setOnMessageCallback(
            [&log](const WebSocketMessagePtr& msg) { log.push(msg); });
        ws.start();

        REQUIRE(peer.acceptWithDeflate("permessage-deflate"));
        REQUIRE(log.waitForOpen());

        // Send the invalid compressed message (possibly fragmented / split).
        sendBad(peer, binary);

        // Wait for the client to emit its one error and start closing
        bool gotError = false;
        for (int i = 0; i < 500; ++i)
        {
            auto ev = log.snapshot();
            if (findEvent(ev, WebSocketMessageType::Error))
            {
                gotError = true;
                break;
            }
            ix::msleep(10);
        }
        REQUIRE(gotError);

        // After the error, more bytes containing valid-looking frames must be
        // completely ignored: no Message, no Ping/Pong events, no pong replies.
        injectAfterError(peer);

        // Inspect the CLOSE frame the client sent (always masked).
        RawPeer::ParsedFrame closeFrame;
        REQUIRE(peer.recvFrame(closeFrame));
        REQUIRE(closeFrame.opcode == 8);
        REQUIRE(closeFrame.payload.size() >= 2);
        uint16_t code = ((uint16_t)(uint8_t) closeFrame.payload[0] << 8) |
                        (uint8_t) closeFrame.payload[1];
        REQUIRE(code == WebSocketCloseConstants::kInvalidFramePayloadData); // 1007
        std::string reason = closeFrame.payload.substr(2);
        REQUIRE_FALSE(reason.empty());

        if (echoClose)
        {
            peer.sendCloseEcho(code, reason, true); // client frames are masked
        }
        // If we don't echo, the client must still close after its wait delay.

        REQUIRE(log.waitUntilClosed());

        // Give any stray events a chance to be wrongly emitted
        ix::msleep(200);

        auto events = log.snapshot();
        auto error = findEvent(events, WebSocketMessageType::Error);
        REQUIRE(error != nullptr);
        REQUIRE(error->decompressionError == true);
        REQUIRE(error->str.empty());
        REQUIRE_FALSE(error->reason.empty());
        REQUIRE(error->wireSize == expectedWireSize);

        REQUIRE(countEvents(events, WebSocketMessageType::Error) == 1);
        REQUIRE(countEvents(events, WebSocketMessageType::Close) == 1);
        REQUIRE(countEvents(events, WebSocketMessageType::Message) == 0);
        REQUIRE(countEvents(events, WebSocketMessageType::Fragment) == 0);
        REQUIRE(countEvents(events, WebSocketMessageType::Ping) == 0);
        REQUIRE(countEvents(events, WebSocketMessageType::Pong) == 0);

        auto close = findEvent(events, WebSocketMessageType::Close);
        REQUIRE(close->closeCode == WebSocketCloseConstants::kInvalidFramePayloadData);
        REQUIRE(close->closeReason == reason);

        REQUIRE(log.sendInErrorCallbackFailed.load());

        ws.stop();
    }

    // A masked client-bound frame is sent by the *server* side unmasked; in
    // this scenario the raw peer acts as server, so frames it sends are
    // unmasked.
    const bool kServerToClientMasked = false;
    // When the raw peer acts as client (server-side test) its frames are
    // masked.
    const bool kClientToServerMasked = true;

} // namespace

TEST_CASE("decompression_failure_client_single_byte", "[deflate][decompression]")
{
    // A single invalid compressed byte 0x07, both text and binary.
    for (int binary = 0; binary < 2; ++binary)
    {
        runClientCase(
            binary == 1,
            true,
            std::string(1, '\x07'),
            1,
            [](RawPeer& peer) {
                // A legal-looking message and a ping right after the bad one
                // in further writes: nothing must be delivered or answered.
                peer.sendFrame(1, true, false, "after-error", kServerToClientMasked);
                peer.sendFrame(9, true, false, "ping-after", kServerToClientMasked);
            },
            [binary](RawPeer& peer, bool bin) {
                int opcode = bin ? 2 : 1;
                peer.sendFrame(opcode, true, true, std::string(1, '\x07'),
                               kServerToClientMasked);
            });
    }
}

TEST_CASE("decompression_failure_client_valid_then_invalid", "[deflate][decompression]")
{
    // A stream that decompresses to a large valid prefix before hitting
    // invalid compressed data. The partial body must never be delivered.
    std::string big(40 * 1024, 'x');
    std::string validPrefix = rawCompress(big);
    std::string bad = validPrefix + std::string(1, '\x07');

    runClientCase(
        false,
        true,
        bad,
        bad.size(),
        [](RawPeer& peer) {
            peer.sendFrame(1, true, false, "after", kServerToClientMasked);
        },
        [&bad](RawPeer& peer, bool) {
            // Byte-by-byte delivery: split header and payload across reads.
            peer.sendByteByByte(
                RawPeer::frame(1, true, true, bad, kServerToClientMasked));
        });
}

TEST_CASE("decompression_failure_client_fragmented", "[deflate][decompression]")
{
    // Compressed payload split across several continuation frames, with a
    // normal Ping/Pong interleaved between fragments. wireSize is the sum of
    // the fragment payloads (headers excluded).
    std::string big(50 * 1024, 'y');
    std::string valid = rawCompress(big);
    std::string bad = valid + std::string(1, '\x07');

    // split into 3 pieces
    size_t third = bad.size() / 3;
    std::string p1 = bad.substr(0, third);
    std::string p2 = bad.substr(third, third);
    std::string p3 = bad.substr(2 * third);
    REQUIRE(p1.size() + p2.size() + p3.size() == bad.size());

    runClientCase(
        false,
        false, // do not echo close: exercise the close wait deadline path
        bad,
        bad.size(),
        [](RawPeer& peer) {
            peer.sendFrame(9, true, false, "late-ping", kServerToClientMasked);
        },
        [&](RawPeer& peer, bool) {
            // first fragment (compressed), continuation, final continuation
            peer.sendFrame(1, false, true, p1, kServerToClientMasked);
            // Interleaved control frames between fragments are legal.
            peer.sendFrame(9, true, false, "mid-ping", kServerToClientMasked);
            peer.sendFrame(0xa, true, false, "mid-pong", kServerToClientMasked);
            peer.sendFrame(0, false, false, p2, kServerToClientMasked);
            peer.sendFrame(0, true, false, p3, kServerToClientMasked);
        });
}

